const activePointers=new Map();
function releasePointer(e){const dir=activePointers.get(e.pointerId);if(!dir)return;activePointers.delete(e.pointerId);touch[dir]=[...activePointers.values()].includes(dir);document.querySelector(`.touch-pad [data-dir="${dir}"]`)?.classList.toggle('down',touch[dir]);}
function releaseAllInput(){activePointers.clear();Object.keys(touch).forEach(dir=>touch[dir]=false);Object.keys(keys).forEach(key=>keys[key]=false);document.querySelectorAll('.touch-pad button.down').forEach(btn=>btn.classList.remove('down'));}
document.querySelectorAll('.touch-pad button[data-dir]').forEach(btn=>{const dir=btn.dataset.dir;btn.addEventListener('pointerdown',e=>{e.preventDefault();activePointers.set(e.pointerId,dir);touch[dir]=true;btn.classList.add('down');try{btn.setPointerCapture(e.pointerId);}catch(_){}});btn.addEventListener('pointerup',releasePointer);btn.addEventListener('pointercancel',releasePointer);btn.addEventListener('lostpointercapture',releasePointer);});
window.addEventListener('pointerup',releasePointer);window.addEventListener('pointercancel',releasePointer);window.addEventListener('blur',releaseAllInput);
document.addEventListener('visibilitychange',()=>{if(document.hidden){releaseAllInput();if(running&&!paused){paused=true;showMsg('Paused while you were away');}}});

