function createDragon(){const p=randomIslandPoint();return{...p,baseX:p.x,baseY:p.y,phase:Math.random()*6,speed:.72,corrupted:true,pattern:'hunt',maxHealth:12,health:12,hitFlash:0,orbTimer:1800,drainUsed:false};}
function moveDragon(d,dt){d.hitFlash=Math.max(0,d.hitFlash-dt);d.phase+=dt*.001;
  d.speed=d.health/d.maxHealth<.5?d.speedBoosted?d.speed:.864:d.speedBoosted?d.speed/.1: d.speed;
  if(d.health/d.maxHealth<.5&&!d.drainUsed){d.drainUsed=true;const reinforcements=[...lobsters,...crabs].sort((a,b)=>Math.hypot(a.x-d.x,a.y-d.y)-Math.hypot(b.x-d.x,b.y-d.y));const source=reinforcements[0];if(source){const amount=Math.min(source.health,3);source.health-=amount;d.health=Math.min(d.maxHealth,d.health+amount);if(source.health<=0){lobsters=lobsters.filter(e=>e!==source);crabs=crabs.filter(e=>e!==source);}d.speedBoosted=true;d.speed*=1.2;showMsg('The dragon drained a subordinate and accelerated!');chirp(330);}}
  const dx=player.x-d.x,dy=player.y-d.y,distance=Math.hypot(dx,dy)||1,speed=d.speed*18*dt/1000,nx=d.x+dx/distance*speed,ny=d.y+dy/distance*speed;if(pointIn(nx,ny))d.x=nx,d.y=ny;
  d.orbTimer-=dt;if(d.orbTimer<=0&&distance>55){d.orbTimer=2200;const vx=dx/distance*190,vy=dy/distance*190;dragonOrbs.push({x:d.x,y:d.y,vx,vy,life:5000});}}

