     .message{position:absolute;left:50%;top:76px;transform:translateX(-50%);padding:9px 16px;background:#063f4ddd;border:1px solid #f8d99288;border-radius:30px;font-weight:700;font-size:13px;white-space:nowrap;opacity:0;transition:opacity .2s;pointer-events:none}
