.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}
.intro-screen{position:absolute;inset:0;z-index:5;display:grid;place-items:center;padding:clamp(16px,4vw,42px);background:radial-gradient(ellipse at 50% 45%,#135d6beF,#052c42f5 76%);transition:opacity .25s,visibility .25s}
.intro-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}
.intro-content{width:min(900px,100%);text-align:center}
.intro-kicker{margin:0 0 8px;color:#b8e3d2;font-size:clamp(10px,1.8vw,13px);font-weight:800;letter-spacing:.24em;text-transform:uppercase}
.intro-content h2{margin:0;color:#ffe4a1;font-size:clamp(30px,6vw,58px);line-height:1;text-shadow:0 5px 20px #001c2b}
.intro-scene{display:grid;grid-template-columns:1fr 1.35fr 1fr;align-items:center;gap:clamp(8px,3vw,30px);margin:clamp(20px,5vh,42px) auto 18px;max-width:760px}
.intro-creatures{display:flex;justify-content:center;align-items:center;gap:clamp(2px,1vw,12px);filter:drop-shadow(0 10px 8px #001b29aa);white-space:nowrap}
.intro-crabs{font-size:clamp(34px,7vw,68px)}.intro-dragon{font-size:clamp(84px,17vw,160px);line-height:.9;animation:intro-float 2.8s ease-in-out infinite}.intro-lobsters{font-size:clamp(34px,7vw,68px)}
@keyframes intro-float{50%{transform:translateY(-9px) rotate(-2deg)}}
.intro-continue{min-width:clamp(160px,25vw,220px);font-size:clamp(16px,2.4vw,21px);padding:16px 28px}
.intro-hint{margin:17px auto 0;color:#d4e9d8;font-size:clamp(11px,1.8vw,14px);line-height:1.5}
@media(max-width:600px){.intro-scene{grid-template-columns:1fr 1fr;grid-template-areas:"dragon dragon" "crabs lobsters" "continue continue";row-gap:14px;margin:17px auto}.intro-dragon{grid-area:dragon;font-size:clamp(90px,27vw,140px)}.intro-crabs{grid-area:crabs}.intro-lobsters{grid-area:lobsters}.intro-continue{grid-area:continue;justify-self:center}}
.card{width:min(440px,95%);padding:clamp(22px,4vw,36px);border:1px solid #ffe4a47d;border-radius:26px;background:linear-gradient(145deg,#0b5963f2,#083c50f5);box-shadow:0 16px 55px #002638aa;text-align:center}

